<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Editor visual · {{ $layout->name }}</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#172033;background:#f4f6fa}*{box-sizing:border-box}body{margin:0}.top{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:12px;padding:12px 20px;background:#fff;border-bottom:1px solid #dfe3eb}.top input{font-size:18px;font-weight:700;border:0;border-bottom:1px solid transparent;padding:7px}.top input:focus{outline:0;border-color:#6366f1}.grow{flex:1}.badge{padding:5px 9px;border-radius:999px;background:#eef2ff;color:#4338ca;font-size:12px}.save{font-size:13px;color:#64748b}.btn{border:1px solid #cbd2dd;background:#fff;border-radius:8px;padding:9px 13px;font-weight:650;cursor:pointer}.btn:hover{background:#f8fafc}.btn.primary{background:#4f46e5;color:#fff;border-color:#4f46e5}.btn:disabled{opacity:.45;cursor:not-allowed}.app{display:grid;grid-template-columns:minmax(540px,1fr) 350px;gap:18px;padding:18px;max-width:1600px;margin:auto}.card{background:#fff;border:1px solid #dfe3eb;border-radius:12px;padding:15px;box-shadow:0 1px 2px #1018280a}h2{font-size:15px;margin:0 0 12px}.templates{display:flex;gap:9px;flex-wrap:wrap}.template{width:132px;text-align:left;padding:8px;border:2px solid #e2e8f0;border-radius:9px;background:#fff;cursor:pointer}.template.active{border-color:#4f46e5;background:#eef2ff}.mini{height:55px;display:grid;gap:3px;background:#cbd5e1;margin-bottom:5px}.mini span{background:#64748b}.workspace{margin-top:16px}.canvas{aspect-ratio:16/9;display:grid;gap:6px;background:#111827;padding:6px;border-radius:10px;overflow:hidden}.canvas.full{grid-template:1fr/1fr}.canvas.columns{grid-template:1fr/repeat(2,1fr)}.canvas.rows{grid-template:repeat(2,1fr)/1fr}.canvas.grid{grid-template:repeat(2,1fr)/repeat(2,1fr)}.canvas.right_sidebar{grid-template:repeat(2,1fr)/2fr 1fr}.canvas.right_sidebar .zone:nth-child(3){grid-column:2;grid-row:1/3}.canvas.left_sidebar{grid-template:repeat(2,1fr)/1fr 2fr}.canvas.left_sidebar .zone:first-child{grid-row:1/3}.zone{position:relative;min-width:0;overflow:hidden;background:#283449;border:2px dashed #64748b;border-radius:6px;color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer}.zone.selected{border:3px solid #818cf8}.zone.drag{background:#3730a3}.zone img{width:100%;height:100%;object-fit:cover}.zone-label{position:absolute;left:7px;top:7px;background:#0f172acc;padding:4px 7px;border-radius:5px;font-size:11px}.zone-count{position:absolute;right:7px;bottom:7px;background:#0f172acc;padding:4px 7px;border-radius:5px;font-size:11px}.empty{text-align:center;color:#cbd5e1;font-size:13px}.library-head{display:flex;gap:8px}.library-head input,.library-head select{min-width:0;padding:9px;border:1px solid #cbd2dd;border-radius:8px}.library{display:grid;grid-template-columns:repeat(auto-fill,minmax(105px,1fr));gap:9px;margin-top:12px;max-height:360px;overflow:auto}.media{position:relative;border:1px solid #dfe3eb;border-radius:8px;overflow:hidden;background:#fff;cursor:grab}.media img{width:100%;aspect-ratio:16/10;object-fit:cover;background:#e2e8f0}.media p{font-size:11px;margin:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.media button{width:100%;border:0;border-top:1px solid #e2e8f0;background:#fff;padding:5px;cursor:pointer;color:#4338ca}.type{position:absolute;top:4px;right:4px;font-size:10px;background:#0f172ccc;color:#fff;padding:3px;border-radius:4px}.side{position:sticky;top:78px;align-self:start}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:650;margin-bottom:5px}.field input,.field select{width:100%;padding:8px;border:1px solid #cbd2dd;border-radius:7px}.playlist{max-height:480px;overflow:auto}.item{border:1px solid #dfe3eb;border-radius:8px;padding:9px;margin:8px 0;background:#fff}.item-title{display:flex;gap:8px;align-items:center;font-size:12px;font-weight:650}.item-title img{width:52px;height:34px;object-fit:cover;border-radius:4px}.item-actions{margin-left:auto;display:flex;gap:3px}.item-actions button{border:0;background:#eef2ff;padding:4px 7px;border-radius:5px;cursor:pointer}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.notice{position:fixed;right:18px;bottom:18px;z-index:40;padding:12px 16px;border-radius:9px;background:#172033;color:#fff;display:none;max-width:420px}.notice.error{background:#b42318}.upload{margin-top:10px;border:2px dashed #cbd5e1;border-radius:8px;padding:10px;text-align:center;font-size:12px}small{color:#64748b}@media(max-width:950px){.app{grid-template-columns:1fr}.side{position:static}.canvas{min-height:300px}.top{flex-wrap:wrap}}
</style></head><body>
<header class="top"><a class="btn" href="{{ route('filament.admin.resources.layouts.index') }}">← Diseños</a><input id="layoutName" value="{{ $layout->name }}" aria-label="Nombre del diseño"><span class="badge">Borrador</span><span id="saveStatus" class="save">Cargando…</span><span class="grow"></span><a class="btn" target="_blank" href="{{ route('preview',['layout'=>$layout]) }}">Vista previa</a><button id="publish" class="btn primary" disabled>Publicar</button></header>
<main class="app"><section><div class="card"><h2>Plantilla de pantalla</h2><div id="templates" class="templates"></div></div><div class="card workspace"><h2>Lienzo 16:9</h2><div id="canvas" class="canvas"></div><small>Arrastra contenidos o archivos desde Finder a cualquier zona. El lienzo representa la composición; la reproducción real está en Vista previa.</small></div><div class="card workspace"><div class="library-head"><input id="search" placeholder="Buscar en la biblioteca…"><select id="filter"><option value="all">Todos</option><option value="image">Imágenes</option><option value="video">Vídeos</option></select><label class="btn">Subir archivos<input id="fileInput" type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime" hidden></label></div><div id="library" class="library"></div></div></section>
<aside class="card side"><h2 id="zoneTitle">Inspector de zona</h2><div id="zoneDefaults"></div><div class="upload">Suelta archivos aquí o <button class="btn" id="zoneUpload">selecciónalos</button></div><div id="playlist" class="playlist"></div></aside></main><div id="notice" class="notice"></div>
<script>
const csrf=document.querySelector('meta[name=csrf-token]').content, urls={state:@json(route('visual-editor.state',$layout)),save:@json(route('visual-editor.save',$layout)),upload:@json(route('visual-editor.upload',$layout)),publish:@json(route('visual-editor.publish',$layout)),preflight:@json(route('storage.preflight'))};
const templateNames=@json($templates), counts={full:1,columns:2,rows:2,grid:4,right_sidebar:3,left_sidebar:3};let state=null,selected=0,timer=null,saving=false,failed=false,queued=false;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), format=b=>b>1073741824?(b/1073741824).toFixed(1)+' GB':(b/1048576).toFixed(1)+' MB';
function notify(message,error=false){const n=$('#notice');n.textContent=message;n.className='notice'+(error?' error':'');n.style.display='block';setTimeout(()=>n.style.display='none',4500)}
async function request(url,options={}){options.headers={Accept:'application/json','X-CSRF-TOKEN':csrf,...options.headers};const r=await fetch(url,options);let j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error(j.message||Object.values(j.errors||{}).flat()[0]||'Error de comunicación');return j}
function defaultZone(i){return{key:'zone_'+(i+1),image_fit_default:'cover',image_duration_default_ms:10000,transition_type:'fade',transition_duration_ms:500,items:[]}}
function render(){renderTemplates();renderCanvas();renderLibrary();renderInspector();$('#publish').disabled=saving||failed||queued;}
function renderTemplates(){const box=$('#templates');box.innerHTML='';Object.entries(templateNames).forEach(([key,name])=>{const b=document.createElement('button');b.className='template '+(state.layout.template_key===key?'active':'');b.innerHTML=`<div class="mini ${key}">${Array.from({length:counts[key]},()=>'<span></span>').join('')}</div><b>${esc(name)}</b>`;b.onclick=()=>changeTemplate(key);box.appendChild(b)})}
function changeTemplate(key){if(key===state.layout.template_key)return;const old=state.layout.zones,newCount=counts[key];if(newCount<old.length){const removed=old.slice(newCount),items=removed.flatMap(z=>z.items);if(items.length&&!confirm(`Esta plantilla elimina ${removed.length} zona(s) con ${items.length} contenido(s). Aceptar los moverá a la última zona disponible; Cancelar conserva todo.`))return;const kept=old.slice(0,newCount);if(items.length)kept[newCount-1].items.push(...items);state.layout.zones=kept}else while(state.layout.zones.length<newCount)state.layout.zones.push(defaultZone(state.layout.zones.length));state.layout.template_key=key;state.layout.zones.forEach((z,i)=>z.key='zone_'+(i+1));selected=Math.min(selected,newCount-1);changed();notify('Plantilla actualizada sin eliminar archivos físicos.')}
function renderCanvas(){const c=$('#canvas');c.className='canvas '+state.layout.template_key;c.innerHTML='';state.layout.zones.forEach((z,i)=>{const d=document.createElement('div');d.className='zone '+(i===selected?'selected':'');d.dataset.index=i;const first=z.items[0];d.innerHTML=first?`<img src="${first.thumbnail}" alt=""><span class="zone-label">Zona ${i+1}</span><span class="zone-count">${z.items.length} contenido(s)</span>`:`<div class="empty">＋<br>Suelta contenido<br><small>Zona ${i+1}</small></div>`;d.onclick=()=>{selected=i;render()};d.ondragover=e=>{e.preventDefault();d.classList.add('drag')};d.ondragleave=()=>d.classList.remove('drag');d.ondrop=e=>dropOnZone(e,i);c.appendChild(d)})}
function renderLibrary(){const q=$('#search').value.toLowerCase(),f=$('#filter').value,l=$('#library');l.innerHTML='';state.media.filter(m=>(f==='all'||m.type===f)&&m.name.toLowerCase().includes(q)).forEach(m=>{const d=document.createElement('div');d.className='media';d.draggable=true;d.ondragstart=e=>e.dataTransfer.setData('application/x-simpleview-media',m.id);d.innerHTML=`<span class="type">${m.type==='video'?'VÍDEO':'IMAGEN'}</span><img src="${m.thumbnail}" alt=""><p title="${esc(m.name)}">${esc(m.name)}</p><button type="button">Añadir a Zona ${selected+1}</button>`;d.querySelector('button').onclick=()=>addMedia(m,selected);l.appendChild(d)})}
function addMedia(m,zone){state.layout.zones[zone].items.push({...m,media_asset_id:m.id,image_duration_ms:null,image_fit:null,transition_type:null,transition_duration_ms:null});selected=zone;changed();notify(`${m.name} añadido a Zona ${zone+1}`)}
function dropOnZone(e,i){e.preventDefault();document.querySelectorAll('.zone').forEach(x=>x.classList.remove('drag'));if(e.dataTransfer.files.length)return uploadFiles([...e.dataTransfer.files],i);const id=+e.dataTransfer.getData('application/x-simpleview-media'),m=state.media.find(x=>x.id===id);if(m)addMedia(m,i)}
function renderInspector(){const z=state.layout.zones[selected];$('#zoneTitle').textContent='Zona '+(selected+1);$('#zoneDefaults').innerHTML=`<div class="row"><div class="field"><label>Duración de imagen por defecto (ms)</label><input data-zone="image_duration_default_ms" type="number" min="250" value="${z.image_duration_default_ms}"></div><div class="field"><label>Ajuste por defecto</label><select data-zone="image_fit_default"><option value="cover" ${z.image_fit_default==='cover'?'selected':''}>Cubrir</option><option value="contain" ${z.image_fit_default==='contain'?'selected':''}>Contener</option></select></div><div class="field"><label>Transición por defecto</label><select data-zone="transition_type"><option value="fade" ${z.transition_type==='fade'?'selected':''}>Fundido</option><option value="cut" ${z.transition_type==='cut'?'selected':''}>Corte</option></select></div><div class="field"><label>Fundido por defecto (ms)</label><input data-zone="transition_duration_ms" type="number" min="0" value="${z.transition_duration_ms}"></div></div>`;document.querySelectorAll('[data-zone]').forEach(el=>el.onchange=()=>{z[el.dataset.zone]=el.type==='number'?+el.value:el.value;changed()});const p=$('#playlist');p.innerHTML='';z.items.forEach((item,i)=>{const d=document.createElement('div');d.className='item';d.draggable=true;d.ondragstart=e=>e.dataTransfer.setData('text/x-index',i);d.ondragover=e=>e.preventDefault();d.ondrop=e=>{e.preventDefault();const from=+e.dataTransfer.getData('text/x-index');if(Number.isInteger(from)){const [x]=z.items.splice(from,1);z.items.splice(i,0,x);changed()}};d.innerHTML=`<div class="item-title"><img src="${item.thumbnail}" alt=""><span>${esc(item.name)}<br><small>${item.type==='video'?`${Math.round((item.duration_ms||0)/1000)} s · ${item.width||'?'}×${item.height||'?'} · ${format(item.size)} · se reproduce completo · sin sonido`:format(item.size)}</small></span><span class="item-actions"><button data-up>↑</button><button data-down>↓</button><button data-remove>×</button></span></div>${item.type==='image'?`<div class="row"><div class="field"><label>Duración (ms)</label><input data-item="image_duration_ms" type="number" placeholder="Predeterminada" value="${item.image_duration_ms??''}"></div><div class="field"><label>Ajuste</label><select data-item="image_fit"><option value="">Predeterminado</option><option value="cover" ${item.image_fit==='cover'?'selected':''}>Cubrir</option><option value="contain" ${item.image_fit==='contain'?'selected':''}>Contener</option></select></div><div class="field"><label>Transición</label><select data-item="transition_type"><option value="">Predeterminada</option><option value="fade" ${item.transition_type==='fade'?'selected':''}>Fundido</option><option value="cut" ${item.transition_type==='cut'?'selected':''}>Corte</option></select></div><div class="field"><label>Fundido (ms)</label><input data-item="transition_duration_ms" type="number" placeholder="Predeterminado" value="${item.transition_duration_ms??''}"></div></div>`:''}`;d.querySelector('[data-remove]').onclick=()=>{z.items.splice(i,1);changed()};d.querySelector('[data-up]').onclick=()=>move(i,-1);d.querySelector('[data-down]').onclick=()=>move(i,1);d.querySelectorAll('[data-item]').forEach(el=>el.onchange=()=>{item[el.dataset.item]=el.value===''?null:(el.type==='number'?+el.value:el.value);changed()});p.appendChild(d)})}
function move(i,delta){const a=state.layout.zones[selected].items,j=i+delta;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];changed()}
function changed(){queued=true;failed=false;$('#saveStatus').textContent='Cambios pendientes…';localStorage.setItem('simpleview-draft-'+state.layout.id,JSON.stringify(state.layout));clearTimeout(timer);timer=setTimeout(save,700);render()}
async function save(){if(saving){queued=true;return}saving=true;queued=false;render();$('#saveStatus').textContent='Guardando…';try{const j=await request(urls.save,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.layout)});localStorage.removeItem('simpleview-draft-'+state.layout.id);failed=false;$('#saveStatus').textContent='Guardado '+new Date(j.saved_at).toLocaleTimeString()}catch(e){failed=true;queued=false;$('#saveStatus').innerHTML='Error al guardar · <button id="retry">Reintentar</button>';setTimeout(()=>{$('#retry')?.addEventListener('click',save)},0);notify(e.message,true)}finally{saving=false;render()}}
async function uploadFiles(files,zone=selected){if(!files.length)return;try{await request(urls.preflight,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sizes:files.map(f=>f.size)})});$('#saveStatus').textContent='Subiendo archivos…';const fd=new FormData;fd.append('zone_key',state.layout.zones[zone].key);files.forEach(f=>fd.append('files[]',f));const j=await request(urls.upload,{method:'POST',body:fd});j.items.forEach(item=>item.error?notify(`${item.name}: ${item.error}`,true):(state.media.unshift(item),addMedia(item,zone)));notify('Subida completada.')}catch(e){notify(e.message,true)}finally{$('#fileInput').value=''}}
$('#layoutName').oninput=e=>{state.layout.name=e.target.value;changed()};$('#search').oninput=renderLibrary;$('#filter').onchange=renderLibrary;$('#fileInput').onchange=e=>uploadFiles([...e.target.files]);$('#zoneUpload').onclick=()=>$('#fileInput').click();$('#publish').onclick=async()=>{if(saving||queued||failed)return notify('Espera a que termine el guardado.',true);if(!confirm('¿Publicar este diseño? Se validarán todas las zonas y archivos.'))return;try{const j=await request(urls.publish,{method:'POST'});notify(j.message)}catch(e){notify(e.message,true)}};
(async()=>{try{state=await request(urls.state);const local=localStorage.getItem('simpleview-draft-'+state.layout.id);if(local&&confirm('Hay cambios locales no guardados. ¿Quieres recuperarlos?'))state.layout=JSON.parse(local);$('#layoutName').value=state.layout.name;$('#saveStatus').textContent='Guardado';render()}catch(e){notify(e.message,true)}})();
</script></body></html>
